import test from 'node:test';
import assert from 'node:assert/strict';
import { balance } from './dist/budget.mjs';
test('built application sums credits and debits and handles empty input', () => {
  assert.equal(balance([25, -5, 10]), '$30.00');
  assert.equal(balance([]), '$0.00');
});

import { mkdir, copyFile } from 'node:fs/promises';
// A build must load the source first, so missing imports are genuine failures.
await import('./src/budget.mjs');
await mkdir('dist', { recursive: true });
for (const file of ['budget.mjs', 'settings.mjs']) await copyFile(`src/${file}`, `dist/${file}`);
console.log('Built budget module into dist');

import { currency } from './settings.mjs';
// TODO: Sum all transactions rather than returning only the first entry.
export function balance(entries) { return `${currency}${(entries[0] ?? 0).toFixed(2)}`; }

